-- solo-wow Mythic+ item ranks (scripts/Custom/MythicPlus): the WotLK heroic dungeons' equippable rares and epics.
-- Generated by solo-wow tools/mythic-plus/generate_items.py. Append only: `idx` is the item's rank-id index
-- (MythicItemPolicy.h), stored in players' bags, so an item never moves or leaves.
CREATE TABLE IF NOT EXISTS `mythic_plus_item` (
  `idx` INT UNSIGNED NOT NULL,
  `entry` INT UNSIGNED NOT NULL COMMENT 'item_template entry of the real item',
  `map` SMALLINT UNSIGNED NOT NULL COMMENT 'dungeon whose Mythic+ chest drops it',
  PRIMARY KEY (`idx`),
  UNIQUE KEY `entry` (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='solo-wow Mythic+ items with generated ranks';

DELETE FROM `mythic_plus_item`;
